//! Finite C13 generic receiver expectations frozen before implementation or runtime.
use ktlsp_parser::{FileKind, Parsed, Parser, ParserError, SourceSnapshot};
use serde_json::{Value, json};
use std::io::Write;
use std::sync::atomic::AtomicBool;

fn declaration(kind: &str) -> bool {
    matches!(
        kind,
        "CLASS" | "OBJECT_DECLARATION" | "FUN" | "PROPERTY" | "TYPEALIAS"
    )
}

fn projection(tree: &Parsed) -> Value {
    let elements = tree.elements();
    Value::Array(
        elements
            .iter()
            .filter(|e| {
                !e.token
                    && (declaration(&e.kind)
                        || matches!(
                            e.kind.as_str(),
                            "TYPE_PARAMETER_LIST"
                                | "TYPE_PARAMETER"
                                | "TYPE_REFERENCE"
                                | "USER_TYPE"
                                | "DYNAMIC_TYPE"
                                | "REFERENCE_EXPRESSION"
                                | "VALUE_PARAMETER_LIST"
                                | "VALUE_PARAMETER"
                                | "TYPE_ARGUMENT_LIST"
                                | "TYPE_PROJECTION"
                                | "ANNOTATION_ENTRY"
                                | "PROPERTY_ACCESSOR"
                        ))
            })
            .map(|e| {
                let mut parent = e.parent;
                let owner = loop {
                    match parent {
                        Some(id) if declaration(&elements[id].kind) => {
                            break Some((elements[id].start, elements[id].end));
                        }
                        Some(id) => parent = elements[id].parent,
                        None => break None,
                    }
                };
                json!([
                    e.kind,
                    e.start,
                    e.end,
                    elements[e.parent.unwrap()].kind,
                    owner
                ])
            })
            .collect(),
    )
}

fn names(tree: &Parsed) -> Value {
    let elements = tree.elements();
    Value::Array(
        elements
            .iter()
            .filter(|e| {
                e.token
                    && e.kind == "IDENTIFIER"
                    && e.parent.is_some_and(|p| declaration(&elements[p].kind))
            })
            .map(|e| {
                json!([
                    elements[e.parent.unwrap()].start,
                    e.start,
                    e.end,
                    &tree.source()[e.start..e.end]
                ])
            })
            .collect(),
    )
}

fn diagnostics(tree: &Parsed) -> Value {
    Value::Array(
        tree.diagnostics()
            .iter()
            .map(|d| json!([d.start, d.end, d.message]))
            .collect(),
    )
}

fn compatibility(tree: &Parsed, case: &Value) {
    let id = case["id"].as_str().unwrap();
    let elements = tree.elements();
    let candidate = case["candidate_start"].as_u64().map(|n| n as usize);
    let top_level_function = |start| {
        elements.iter().any(|e| {
            !e.token
                && e.kind == "FUN"
                && e.start == start
                && e.parent.is_some_and(|p| elements[p].kind == "KT_FILE")
        })
    };
    match case["mode"].as_str().unwrap() {
        "classifier-retains-candidate" => {
            let start = candidate.unwrap();
            let class = elements
                .iter()
                .find(|e| !e.token && e.kind == "CLASS" && e.start == 0)
                .unwrap();
            assert!(class.end > start, "{id}");
            let list = elements
                .iter()
                .find(|e| {
                    !e.token
                        && e.kind == "TYPE_PARAMETER_LIST"
                        && e.start == case["list_start"].as_u64().unwrap() as usize
                })
                .unwrap();
            let owner = &elements[list.parent.unwrap()];
            assert_eq!((owner.kind.as_str(), owner.start), ("CLASS", 0), "{id}");
            assert!(list.end > start, "{id}");
            assert!(!top_level_function(start), "{id}");
            assert!(!tree.diagnostics().is_empty(), "{id}");
        }
        "nonclassifier-gate" => {
            let list = elements
                .iter()
                .find(|e| {
                    !e.token
                        && e.kind == "TYPE_PARAMETER_LIST"
                        && e.start == case["list_start"].as_u64().unwrap() as usize
                })
                .unwrap();
            let owner = &elements[list.parent.unwrap()];
            assert_eq!(
                (owner.kind.as_str(), owner.start),
                (case["original_owner"].as_str().unwrap(), 0),
                "{id}"
            );
            assert!(!top_level_function(candidate.unwrap()), "{id}");
        }
        "nested-function-ownership" => {
            let functions: Vec<_> = elements
                .iter()
                .enumerate()
                .filter(|(_, e)| !e.token && e.kind == "FUN" && e.start == candidate.unwrap())
                .collect();
            assert_eq!(functions.len(), 1, "{id}");
            let (index, function) = functions[0];
            assert_eq!(
                elements[function.parent.unwrap()].kind,
                case["function_parent"].as_str().unwrap(),
                "{id}"
            );
            assert!(!top_level_function(function.start), "{id}");
            let direct_names: Vec<_> = elements
                .iter()
                .filter(|e| e.token && e.kind == "IDENTIFIER" && e.parent == Some(index))
                .map(|e| &tree.source()[e.start..e.end])
                .collect();
            let expected: Vec<_> = case["direct_name"].as_str().into_iter().collect();
            assert_eq!(direct_names, expected, "{id}");
        }
        "aggregate" => {
            let declined = case["declined_start"].as_u64().unwrap() as usize;
            let recovered = case["recovered_start"].as_u64().unwrap() as usize;
            let class = elements
                .iter()
                .find(|e| !e.token && e.kind == "CLASS" && e.start == 0)
                .unwrap();
            assert!(class.end > declined, "{id}");
            assert!(!top_level_function(declined), "{id}");
            let fresh = elements
                .iter()
                .find(|e| {
                    !e.token
                        && e.kind == "CLASS"
                        && e.start == case["fresh_start"].as_u64().unwrap() as usize
                })
                .unwrap();
            assert!(fresh.end < recovered, "{id}");
            assert!(top_level_function(recovered), "{id}");
            let function = elements
                .iter()
                .find(|e| !e.token && e.kind == "FUN" && e.start == recovered)
                .unwrap();
            assert_eq!(function.end, tree.source().len(), "{id}");
        }
        mode => panic!("{id}: unexpected control {mode}"),
    }
}

#[test]
fn frozen_generic_receiver_contract_through_production_snapshot_worker() {
    let contract: Value = serde_json::from_str(FIXTURES).unwrap();
    let cases = contract["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 84);
    assert_eq!(
        cases
            .iter()
            .filter(|c| c.get("projection").is_some())
            .count(),
        26
    );
    let erratum: Value = serde_json::from_str(MALFORMED_PREFIX_ERRATUM).unwrap();
    let nullable_amendments: Value = serde_json::from_str(NULLABLE_RECEIVER_AMENDMENTS).unwrap();
    assert_eq!(
        cases
            .iter()
            .filter(|c| c["id"] == "malformed-annotation-prefix")
            .count(),
        1
    );
    let parser = Parser::new(env!("CARGO_BIN_EXE_ktlsp-parser-worker")).unwrap();
    for case in cases {
        let id = case["id"].as_str().unwrap();
        let source = case["source"].as_str().unwrap();
        assert_eq!(
            source.len(),
            case["bytes"].as_u64().unwrap() as usize,
            "{id}"
        );
        let snapshot = SourceSnapshot::new(id, 1, FileKind::Source, source).unwrap();
        let accepted = parser
            .parse_snapshot(&snapshot, &AtomicBool::new(false))
            .unwrap_or_else(|error| panic!("{id}: {error:?}"));
        assert_eq!(accepted.snapshot(), &snapshot, "{id}");
        let tree = accepted.tree_for(&snapshot).unwrap();
        assert_eq!(tree.source(), source, "{id}");
        let old_elements = serde_json::to_value(tree.elements()).unwrap();
        let old_diagnostics = serde_json::to_value(tree.diagnostics()).unwrap();
        let mut cursor = 0;
        for e in tree.elements().iter().filter(|e| e.token) {
            assert_eq!(e.start, cursor, "{id}");
            assert!(
                source.is_char_boundary(e.start) && source.is_char_boundary(e.end),
                "{id}"
            );
            cursor = e.end;
        }
        assert_eq!(cursor, source.len(), "{id}");
        // This source-derived erratum supersedes only the malformed-prefix ownership assumption.
        let expected_case = if id == "malformed-annotation-prefix" {
            assert_eq!(source, erratum["source"].as_str().unwrap(), "{id}");
            &erratum
        } else if matches!(id, "safe-nullable-receiver" | "spaced-nullable-receiver") {
            let expected = nullable_amendments["cases"]
                .as_array()
                .unwrap()
                .iter()
                .find(|c| c["id"].as_str() == Some(id))
                .unwrap();
            assert_eq!(source, expected["source"].as_str().unwrap(), "{id}");
            expected
        } else {
            case
        };
        if let Some(expected) = expected_case.get("projection") {
            assert_eq!(&projection(tree), expected, "{id}");
            assert_eq!(names(tree), expected_case["declaration_names"], "{id}");
            assert_eq!(diagnostics(tree), expected_case["diagnostics"], "{id}");
            for expected in expected_case["tokens"].as_array().unwrap() {
                let start = expected[1].as_u64().unwrap() as usize;
                let end = expected[2].as_u64().unwrap() as usize;
                let matches: Vec<_> = tree
                    .elements()
                    .iter()
                    .filter(|e| {
                        e.token
                            && e.kind == expected[0].as_str().unwrap()
                            && (e.start, e.end) == (start, end)
                    })
                    .collect();
                assert_eq!(matches.len(), 1, "{id}: {expected}");
                assert_eq!(
                    tree.elements()[matches[0].parent.unwrap()].kind,
                    expected[4].as_str().unwrap(),
                    "{id}"
                );
                assert_eq!(&source[start..end], expected[3].as_str().unwrap(), "{id}");
            }
            for (offset, expected) in expected_case["positions"].as_object().unwrap() {
                let offset = offset.parse::<usize>().unwrap();
                if expected.is_string() {
                    assert!(tree.position(offset).is_err(), "{id}: {offset}");
                } else {
                    let actual = tree.position(offset).unwrap();
                    assert_eq!(
                        json!([actual.line, actual.character]),
                        *expected,
                        "{id}: {offset}"
                    );
                }
            }
            if let Some(errors) = expected_case.get("error_ownership") {
                let elements = tree.elements();
                assert!(
                    !elements
                        .iter()
                        .any(|e| !e.token && e.kind == "ANNOTATION_ENTRY"),
                    "{id}"
                );
                for expected in errors.as_array().unwrap() {
                    let start = expected[0].as_u64().unwrap() as usize;
                    let end = expected[1].as_u64().unwrap() as usize;
                    let matches: Vec<_> = elements
                        .iter()
                        .filter(|e| {
                            !e.token
                                && e.kind == "ERROR_ELEMENT"
                                && (e.start, e.end) == (start, end)
                        })
                        .collect();
                    assert_eq!(matches.len(), 1, "{id}: {expected}");
                    let mut parent = matches[0].parent;
                    assert_eq!(
                        elements[parent.unwrap()].kind,
                        expected[2].as_str().unwrap(),
                        "{id}"
                    );
                    let owner = loop {
                        match parent {
                            Some(index) if declaration(&elements[index].kind) => {
                                break json!([
                                    elements[index].kind,
                                    elements[index].start,
                                    elements[index].end
                                ]);
                            }
                            Some(index) => parent = elements[index].parent,
                            None => break Value::Null,
                        }
                    };
                    assert_eq!(owner, expected[3], "{id}");
                }
                for expected in expected_case["original_partitions"].as_array().unwrap() {
                    let kind = expected[0].as_str().unwrap();
                    let start = expected[1].as_u64().unwrap() as usize;
                    let end = expected[2].as_u64().unwrap() as usize;
                    assert_eq!(
                        elements
                            .iter()
                            .filter(|e| e.kind == kind
                                && e.token == (kind == "WHITE_SPACE")
                                && (e.start, e.end) == (start, end))
                            .count(),
                        1,
                        "{id}: {expected}"
                    );
                }
            }
        } else {
            compatibility(tree, expected_case);
        }
        for changed in [
            SourceSnapshot::new(id, 2, FileKind::Source, source).unwrap(),
            SourceSnapshot::new(format!("{id}-other"), 1, FileKind::Source, source).unwrap(),
            SourceSnapshot::new(id, 1, FileKind::Script, source).unwrap(),
            SourceSnapshot::new(id, 1, FileKind::Source, format!("{source} ")).unwrap(),
        ] {
            assert_eq!(
                accepted.tree_for(&changed).unwrap_err(),
                ParserError::StaleSnapshot,
                "{id}"
            );
        }
        let healthy = SourceSnapshot::new(id, 2, FileKind::Source, "fun healthy() = 2").unwrap();
        assert_eq!(
            accepted.tree_for(&healthy).unwrap_err(),
            ParserError::StaleSnapshot,
            "{id}"
        );
        let followup = parser
            .parse_snapshot(&healthy, &AtomicBool::new(false))
            .unwrap();
        assert_eq!(followup.snapshot(), &healthy, "{id}");
        let next = followup.tree_for(&healthy).unwrap();
        assert_eq!(next.source(), healthy.source(), "{id}");
        assert_eq!(
            projection(next),
            contract["healthy_followup"]["projection"],
            "{id}"
        );
        assert_eq!(
            names(next),
            contract["healthy_followup"]["declaration_names"],
            "{id}"
        );
        assert_eq!(
            diagnostics(next),
            contract["healthy_followup"]["diagnostics"],
            "{id}"
        );
        let old = accepted.tree_for(&snapshot).unwrap();
        assert_eq!(snapshot.source(), source, "{id}");
        assert_eq!(old.source(), source, "{id}");
        assert_eq!(
            serde_json::to_value(old.elements()).unwrap(),
            old_elements,
            "{id}"
        );
        assert_eq!(
            serde_json::to_value(old.diagnostics()).unwrap(),
            old_diagnostics,
            "{id}"
        );
        writeln!(
            std::io::stderr().lock(),
            "C13 generic receiver first outcome: {id}: passed"
        )
        .unwrap();
    }
}

